import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import api from "../services/api"; // axios instance

export default function Login() {
  const navigate = useNavigate();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [modules, setModules] = useState([]);
  const [showModuleSelect, setShowModuleSelect] = useState(false);
  const [selectedModule, setSelectedModule] = useState("");

  // 1️⃣ Login handler
  const loginUser = async (e) => {
    e.preventDefault();
    setError("");

    try {
      const res = await api.post("/auth/login", { email, password });

      // Save token and user info
      localStorage.setItem("token", res.data.token);
      localStorage.setItem("user", JSON.stringify(res.data.user));

      if (res.data.modules && res.data.modules.length > 1) {
        // Multiple modules → show selection dropdown
        setModules(res.data.modules);
        setShowModuleSelect(true);
      } else if (res.data.modules.length === 1) {
        // Only one module → redirect directly
        navigate(res.data.modules[0].module_path);
      } else {
        setError("No modules assigned to this user.");
      }

    } catch (err) {
      console.error(err);
      setError(err.response?.data?.message || "Login failed");
    }
  };

  // 2️⃣ Enter selected module
  const enterModule = () => {
    if (!selectedModule) {
      alert("Please select a module");
      return;
    }
    navigate(selectedModule);
  };

  return (
    <div className="d-flex justify-content-center align-items-center vh-100">
      {!showModuleSelect ? (
        <form
          onSubmit={loginUser}
          className="p-4 border rounded bg-white"
          style={{ width: "350px" }}
        >
          <h3 className="text-center mb-3">Login</h3>

          {error && <p className="text-danger">{error}</p>}

          <div className="mb-3">
            <input
              type="email"
              className="form-control"
              placeholder="Email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
          </div>

          <div className="mb-3">
            <input
              type="password"
              className="form-control"
              placeholder="Password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
          </div>

          <button type="submit" className="btn btn-primary w-100">
            Login
          </button>
        </form>
      ) : (
        <div className="p-4 border rounded bg-white" style={{ width: "350px" }}>
          <h4 className="text-center mb-3">Select Module</h4>
          <select
            className="form-control mb-2"
            onChange={(e) => setSelectedModule(e.target.value)}
            value={selectedModule}
          >
            <option value="">-- Choose Module --</option>
            {modules.map((m) => (
              <option key={m.module_id} value={m.module_path}>
                {m.module_name} ({m.role_name})
              </option>
            ))}
          </select>
          <button className="btn btn-success w-100" onClick={enterModule}>
            Enter Module
          </button>
        </div>
      )}
    </div>
  );
}
